use crate::actions::Target;
use crate::cards::{CardBehavior, CardData, TargetRequirement, CardRegistry};
use crate::ids::ObjectId;
use crate::state::{GameState, UntilEndOfTurnKeyword};
use crate::types::*;

/// Spidery Grasp — {2}{G} instant. Untap target creature. It gets +2/+4 and gains reach until end of turn.
pub struct SpideryGrasp;

impl CardBehavior for SpideryGrasp {
    fn card_data(&self) -> CardData {
        CardData {
            name: "Spidery Grasp".into(),
            cost: Some(ManaCost::new(vec![
                ManaSymbol::Generic(2),
                ManaSymbol::Colored(Color::Green),
            ])),
            card_types: vec![CardType::Instant],
            supertypes: vec![],
            subtypes: vec![],
            power: None,
            toughness: None,
            oracle_text: "Untap target creature. It gets +2/+4 and gains reach until end of turn.".into(),
            keywords: vec![],
            flashback_cost: None, continuous_effects: vec![], additional_cost: None, triggered_abilities: vec![],
        }
    }

    fn target_requirement(&self) -> TargetRequirement {
        TargetRequirement::Creature
    }

    fn on_resolve(&self, state: &mut GameState, object_id: ObjectId, targets: &[Target], _registry: &CardRegistry) {
        if let Some(Target::Object(target_id)) = targets.first() {
            if state.get_object(*target_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
                // Untap the target creature.
                if let Some(target) = state.get_object_mut(*target_id) {
                    target.tapped = false;
                }
                state.until_end_of_turn_effects.push(
                    crate::state::UntilEndOfTurnEffect {
                        target: *target_id,
                        power_mod: 2,
                        toughness_mod: 4,
                    }
                );
                state.until_end_of_turn_keywords.push(
                    UntilEndOfTurnKeyword {
                        target: *target_id,
                        keyword: Keyword::Reach,
                    }
                );
            }
        }
        state.move_spell_after_resolve(object_id);
    }
}

